-- SDKWork promotion consolidated initialization baseline (postgres, commerce schema)
-- Generated by reset-database-initialization-state.mjs
-- Application is in initialization state: full DDL lives here; migrations/ is reserved for post-GA changes.
--
-- The promotion capability shares the federated commerce database with payment/order/account
-- capabilities. Identifiers, tenants, timestamps, and money amounts are stored as TEXT so the
-- app-side (claim/redeem) and admin-side repositories operate on one canonical schema.
-- Lifecycle statuses are VARCHAR state machines (see STATE_MACHINES in this file's tables).

-- baseline source: ddl/baseline/postgres/0001_promotion_baseline.sql
-- sdkwork:migration
-- id: 0001_promotion_core
-- engine: postgres
-- module: promotion
-- purpose: L2 promotion offer, coupon stock, code, user coupon, ledger, discount application
-- reversible: true
-- transactional: true

CREATE TABLE IF NOT EXISTS promotion_campaign (
    id TEXT PRIMARY KEY,
    uuid VARCHAR(64) NOT NULL UNIQUE,
    tenant_id TEXT NOT NULL,
    organization_id TEXT,
    campaign_no VARCHAR(128) NOT NULL,
    campaign_code VARCHAR(128),
    display_name VARCHAR(256) NOT NULL,
    description VARCHAR(1024),
    channel_scope VARCHAR(32) NOT NULL DEFAULT 'ALL',
    audience_scope VARCHAR(32) NOT NULL DEFAULT 'ALL',
    starts_at TEXT NOT NULL,
    ends_at TEXT,
    status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',
    version BIGINT NOT NULL DEFAULT 0,
    created_by TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CONSTRAINT uk_promotion_campaign_no UNIQUE (tenant_id, campaign_no)
);

CREATE INDEX IF NOT EXISTS idx_promotion_campaign_tenant_status
    ON promotion_campaign (tenant_id, organization_id, status, starts_at DESC);

CREATE TABLE IF NOT EXISTS promotion_offer (
    id TEXT PRIMARY KEY,
    uuid VARCHAR(64) NOT NULL UNIQUE,
    tenant_id TEXT NOT NULL,
    organization_id TEXT,
    campaign_id TEXT,
    offer_no VARCHAR(128) NOT NULL,
    offer_code VARCHAR(128),
    offer_type VARCHAR(32) NOT NULL,
    audience_scope VARCHAR(32) NOT NULL DEFAULT 'ALL',
    combinability VARCHAR(32) NOT NULL DEFAULT 'EXCLUSIVE',
    priority INTEGER NOT NULL DEFAULT 0,
    goods_scope VARCHAR(32) NOT NULL DEFAULT 'BOTH',
    current_offer_version_id TEXT,
    display_name VARCHAR(256) NOT NULL,
    description VARCHAR(1024),
    starts_at TEXT NOT NULL,
    ends_at TEXT,
    status VARCHAR(32) NOT NULL DEFAULT 'active',
    version BIGINT NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CONSTRAINT uk_promotion_offer_no UNIQUE (tenant_id, offer_no)
);

CREATE INDEX IF NOT EXISTS idx_promotion_offer_tenant_status
    ON promotion_offer (tenant_id, organization_id, status, priority DESC, starts_at DESC);
CREATE INDEX IF NOT EXISTS idx_promotion_offer_tenant_type
    ON promotion_offer (tenant_id, offer_type, status);
CREATE INDEX IF NOT EXISTS idx_promotion_offer_campaign
    ON promotion_offer (tenant_id, organization_id, campaign_id, status);

CREATE TABLE IF NOT EXISTS promotion_offer_version (
    id TEXT PRIMARY KEY,
    uuid VARCHAR(64) NOT NULL UNIQUE,
    tenant_id TEXT NOT NULL,
    organization_id TEXT,
    offer_id TEXT NOT NULL,
    version_no INTEGER NOT NULL,
    lifecycle_status VARCHAR(32) NOT NULL DEFAULT 'published',
    discount_type VARCHAR(32) NOT NULL,
    discount_value TEXT NOT NULL DEFAULT '0',
    minimum_amount TEXT NOT NULL DEFAULT '0',
    maximum_discount_amount TEXT,
    maximum_quantity_per_order INTEGER NOT NULL DEFAULT 1,
    currency_code VARCHAR(10) NOT NULL DEFAULT '',
    rule_json TEXT,
    stack_rule_json TEXT,
    published_at TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CONSTRAINT uk_promotion_offer_version_unique UNIQUE (tenant_id, offer_id, version_no)
);

CREATE INDEX IF NOT EXISTS idx_promotion_offer_version_offer
    ON promotion_offer_version (tenant_id, offer_id, version_no DESC);

CREATE TABLE IF NOT EXISTS promotion_coupon_stock (
    id TEXT PRIMARY KEY,
    uuid VARCHAR(64) NOT NULL UNIQUE,
    tenant_id TEXT NOT NULL,
    organization_id TEXT,
    offer_id TEXT NOT NULL,
    offer_version_id TEXT NOT NULL,
    stock_no VARCHAR(128) NOT NULL,
    stock_type VARCHAR(32) NOT NULL,
    code_issue_mode VARCHAR(16) NOT NULL DEFAULT 'REALTIME',
    total_quantity BIGINT NOT NULL DEFAULT 0,
    available_quantity BIGINT NOT NULL DEFAULT 0,
    claimed_quantity BIGINT NOT NULL DEFAULT 0,
    redeemed_quantity BIGINT NOT NULL DEFAULT 0,
    locked_quantity BIGINT NOT NULL DEFAULT 0,
    per_user_limit INTEGER NOT NULL DEFAULT 1,
    claim_starts_at TEXT,
    claim_ends_at TEXT,
    status VARCHAR(32) NOT NULL DEFAULT 'active',
    version BIGINT NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CONSTRAINT uk_promotion_coupon_stock_no UNIQUE (tenant_id, stock_no),
    CONSTRAINT chk_promotion_coupon_stock_quantities_non_negative CHECK (
        total_quantity >= 0 AND available_quantity >= 0 AND claimed_quantity >= 0
        AND redeemed_quantity >= 0 AND locked_quantity >= 0
    ),
    CONSTRAINT chk_promotion_coupon_stock_available_le_total CHECK (
        stock_type = 'UNLIMITED' OR (available_quantity + claimed_quantity <= total_quantity)
    )
);

CREATE INDEX IF NOT EXISTS idx_promotion_coupon_stock_offer
    ON promotion_coupon_stock (tenant_id, offer_id, status);

CREATE TABLE IF NOT EXISTS promotion_code_batch (
    id TEXT PRIMARY KEY,
    uuid VARCHAR(64) NOT NULL UNIQUE,
    tenant_id TEXT NOT NULL,
    organization_id TEXT,
    stock_id TEXT NOT NULL,
    offer_id TEXT NOT NULL,
    offer_version_id TEXT NOT NULL,
    batch_no VARCHAR(128) NOT NULL,
    code_type VARCHAR(32) NOT NULL,
    requested_quantity BIGINT NOT NULL,
    generated_quantity BIGINT NOT NULL DEFAULT 0,
    code_length INTEGER NOT NULL DEFAULT 16,
    code_prefix VARCHAR(32) NOT NULL DEFAULT '',
    starts_at TEXT,
    expires_at TEXT,
    status VARCHAR(32) NOT NULL DEFAULT 'PENDING',
    idempotency_key VARCHAR(200) NOT NULL,
    created_by TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CONSTRAINT uk_promotion_code_batch_no UNIQUE (tenant_id, batch_no),
    CONSTRAINT uk_promotion_code_batch_idempotency UNIQUE (tenant_id, idempotency_key),
    CONSTRAINT chk_promotion_code_batch_quantity CHECK (requested_quantity > 0 AND generated_quantity >= 0 AND generated_quantity <= requested_quantity),
    CONSTRAINT chk_promotion_code_batch_length CHECK (code_length BETWEEN 12 AND 32)
);

CREATE INDEX IF NOT EXISTS idx_promotion_code_batch_stock
    ON promotion_code_batch (tenant_id, organization_id, stock_id, status, created_at DESC);

CREATE TABLE IF NOT EXISTS promotion_code (
    id TEXT PRIMARY KEY,
    uuid VARCHAR(64) NOT NULL UNIQUE,
    tenant_id TEXT NOT NULL,
    organization_id TEXT,
    code_batch_id TEXT,
    stock_id TEXT NOT NULL,
    offer_id TEXT NOT NULL,
    offer_version_id TEXT NOT NULL,
    code_no VARCHAR(128) NOT NULL,
    promotion_code VARCHAR(128) NOT NULL,
    code_type VARCHAR(32) NOT NULL,
    max_claims INTEGER NOT NULL DEFAULT 1,
    claimed_quantity INTEGER NOT NULL DEFAULT 0,
    starts_at TEXT,
    expires_at TEXT,
    status VARCHAR(32) NOT NULL DEFAULT 'active',
    version BIGINT NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CONSTRAINT uk_promotion_code_no UNIQUE (tenant_id, code_no),
    CONSTRAINT uk_promotion_code_value UNIQUE (tenant_id, promotion_code),
    CONSTRAINT chk_promotion_code_claimed_le_max CHECK (claimed_quantity <= max_claims)
);

CREATE INDEX IF NOT EXISTS idx_promotion_code_stock
    ON promotion_code (tenant_id, stock_id, status);
CREATE INDEX IF NOT EXISTS idx_promotion_code_batch
    ON promotion_code (tenant_id, code_batch_id, status);

CREATE TABLE IF NOT EXISTS promotion_user_coupon (
    id TEXT PRIMARY KEY,
    uuid VARCHAR(64) NOT NULL UNIQUE,
    tenant_id TEXT NOT NULL,
    organization_id TEXT,
    coupon_no VARCHAR(128) NOT NULL,
    stock_id TEXT NOT NULL,
    code_id TEXT,
    offer_id TEXT NOT NULL,
    offer_version_id TEXT NOT NULL,
    subject_type VARCHAR(32) NOT NULL,
    subject_id TEXT NOT NULL,
    owner_user_id TEXT NOT NULL,
    coupon_code VARCHAR(128) NOT NULL,
    status VARCHAR(32) NOT NULL DEFAULT 'claimed',
    claimed_at TEXT NOT NULL,
    valid_from TEXT NOT NULL,
    expires_at TEXT,
    redeemed_at TEXT,
    disabled_at TEXT,
    source_type VARCHAR(64),
    source_id TEXT,
    request_no VARCHAR(128) NOT NULL,
    idempotency_key VARCHAR(200) NOT NULL,
    trace_id VARCHAR(128) NOT NULL DEFAULT '',
    version BIGINT NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CONSTRAINT uk_promotion_user_coupon_no UNIQUE (tenant_id, coupon_no),
    CONSTRAINT uk_promotion_user_coupon_code UNIQUE (tenant_id, coupon_code),
    CONSTRAINT uk_promotion_user_coupon_idempotency UNIQUE (tenant_id, idempotency_key)
);

CREATE INDEX IF NOT EXISTS idx_promotion_user_coupon_owner_status_expires
    ON promotion_user_coupon (tenant_id, owner_user_id, status, expires_at);
CREATE INDEX IF NOT EXISTS idx_promotion_user_coupon_offer
    ON promotion_user_coupon (tenant_id, offer_id, status);

CREATE TABLE IF NOT EXISTS promotion_distribution_task (
    id TEXT PRIMARY KEY,
    uuid VARCHAR(64) NOT NULL UNIQUE,
    tenant_id TEXT NOT NULL,
    organization_id TEXT,
    stock_id TEXT NOT NULL,
    offer_id TEXT NOT NULL,
    offer_version_id TEXT NOT NULL,
    task_no VARCHAR(128) NOT NULL,
    distribution_type VARCHAR(32) NOT NULL DEFAULT 'DIRECT',
    requested_quantity BIGINT NOT NULL,
    succeeded_quantity BIGINT NOT NULL DEFAULT 0,
    failed_quantity BIGINT NOT NULL DEFAULT 0,
    status VARCHAR(32) NOT NULL DEFAULT 'PENDING',
    idempotency_key VARCHAR(200) NOT NULL,
    created_by TEXT NOT NULL,
    started_at TEXT,
    completed_at TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CONSTRAINT uk_promotion_distribution_task_no UNIQUE (tenant_id, task_no),
    CONSTRAINT uk_promotion_distribution_task_idempotency UNIQUE (tenant_id, idempotency_key),
    CONSTRAINT chk_promotion_distribution_task_quantities CHECK (requested_quantity > 0 AND succeeded_quantity >= 0 AND failed_quantity >= 0 AND succeeded_quantity + failed_quantity <= requested_quantity)
);

CREATE INDEX IF NOT EXISTS idx_promotion_distribution_task_stock
    ON promotion_distribution_task (tenant_id, organization_id, stock_id, status, created_at DESC);

CREATE TABLE IF NOT EXISTS promotion_distribution_record (
    id TEXT PRIMARY KEY,
    uuid VARCHAR(64) NOT NULL UNIQUE,
    tenant_id TEXT NOT NULL,
    organization_id TEXT,
    task_id TEXT NOT NULL,
    owner_user_id TEXT NOT NULL,
    user_coupon_id TEXT,
    status VARCHAR(32) NOT NULL,
    failure_code VARCHAR(64),
    failure_detail VARCHAR(512),
    created_at TEXT NOT NULL,
    CONSTRAINT uk_promotion_distribution_record_target UNIQUE (tenant_id, task_id, owner_user_id)
);

CREATE INDEX IF NOT EXISTS idx_promotion_distribution_record_task
    ON promotion_distribution_record (tenant_id, task_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_promotion_distribution_record_owner
    ON promotion_distribution_record (tenant_id, owner_user_id, created_at DESC);

CREATE TABLE IF NOT EXISTS promotion_coupon_ledger_entry (
    id TEXT PRIMARY KEY,
    uuid VARCHAR(64) NOT NULL UNIQUE,
    tenant_id TEXT NOT NULL,
    stock_id TEXT NOT NULL,
    user_coupon_id TEXT,
    offer_id TEXT NOT NULL,
    subject_type VARCHAR(32),
    subject_id TEXT,
    direction VARCHAR(16) NOT NULL,
    quantity_delta BIGINT NOT NULL,
    balance_after BIGINT NOT NULL,
    business_type VARCHAR(64) NOT NULL,
    business_no VARCHAR(128) NOT NULL,
    request_no VARCHAR(128) NOT NULL,
    idempotency_key VARCHAR(200) NOT NULL,
    source_type VARCHAR(64),
    source_id TEXT,
    trace_id VARCHAR(128) NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    CONSTRAINT uk_promotion_coupon_ledger_entry_idempotency UNIQUE (tenant_id, idempotency_key)
