CREATE INDEX IF NOT EXISTS idx_promotion_coupon_ledger_entry_stock_created
    ON promotion_coupon_ledger_entry (tenant_id, stock_id, created_at DESC);

CREATE TABLE IF NOT EXISTS promotion_discount_application (
    id TEXT PRIMARY KEY,
    uuid VARCHAR(64) NOT NULL UNIQUE,
    tenant_id TEXT NOT NULL,
    organization_id TEXT,
    application_no VARCHAR(128) NOT NULL,
    order_id TEXT NOT NULL,
    order_no VARCHAR(128),
    user_coupon_id TEXT,
    offer_id TEXT NOT NULL,
    offer_version_id TEXT NOT NULL,
    subject_type VARCHAR(32) NOT NULL,
    subject_id TEXT NOT NULL,
    owner_user_id TEXT NOT NULL,
    discount_type VARCHAR(32) NOT NULL,
    discount_amount TEXT NOT NULL,
    currency_code VARCHAR(10) NOT NULL DEFAULT '',
    discount_details_json TEXT,
    goods_type VARCHAR(32) NOT NULL DEFAULT 'BOTH',
    status VARCHAR(32) NOT NULL DEFAULT 'applied',
    applied_at TEXT NOT NULL,
    settled_at TEXT,
    released_at TEXT,
    rolled_back_at TEXT,
    release_reason VARCHAR(512),
    rollback_reason VARCHAR(512),
    request_no VARCHAR(128) NOT NULL,
    idempotency_key VARCHAR(200) NOT NULL,
    trace_id VARCHAR(128) NOT NULL DEFAULT '',
    version BIGINT NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CONSTRAINT uk_promotion_discount_application_no UNIQUE (tenant_id, application_no),
    CONSTRAINT uk_promotion_discount_application_idempotency UNIQUE (tenant_id, idempotency_key)
